export function techAt(year) {
  let apt = 0, fit = 1;
  const biz = new Set(BUSINESSES.filter(b => b.year <= year).map(b => b.id));
  for (const t of TECH) {
    if (t.year > year) break;
    if (t.apt) apt = t.apt;
    if (t.fit) fit = t.fit;
  }
  return { apt, fit, biz };
}
